import json
OUT=[]; Q={}
def P(slug,country,name,en,years,era,eraNote,life,works,look,activeIn=None,also=None,copyrighted=None):
    ws=[]
    for i,(t,o,y,m,l,q) in enumerate(works):
        w=dict(title=t,orig=o,year=y,museum=m,look=l)
        if q: iid=f"{slug}-{i+1}"; w['img']=iid; Q[iid]=(q,en)
        ws.append(w)
    d=dict(slug=slug,country=country,name=name,en=en,years=years,era=era,eraNote=eraNote,life=life,works=ws,howToLook=look)
    if activeIn: d['activeIn']=activeIn
    if also: d['also']=also
    if copyrighted: d['copyrighted']=copyrighted
    OUT.append(d)
